typedef float Real;

extern const Real BfmeZeroRange;

struct BfmeShadowVector3
{
	Real x, y, z;
};

struct BfmeShadowIndexTriple
{
	unsigned short i0, i1, i2;
};

struct BfmeShadowIndexResource
{
	unsigned char m_unreconstructed_00[0xc];
	BfmeShadowIndexTriple *m_indices;
};

struct BfmeShadowMeshGeometry
{
	unsigned char m_unreconstructed_00[0x24];
	int m_numPolygon;
	unsigned char m_unreconstructed_28[0x2c - 0x28];
	BfmeShadowIndexResource *m_lock;
};

struct BfmeShadowMesh
{
	unsigned char m_unreconstructed_00[0xc8];
	BfmeShadowMeshGeometry *m_geometry;
};

struct BfmeShadowBufferEntry
{
	BfmeShadowMesh *m_mesh;
	BfmeShadowVector3 *m_vertices;
	unsigned char *m_flags;
	void *m_allocation2;
	unsigned int m_reserved10;
	unsigned char m_reserved14;

	void fill(unsigned char *value);
};

void BfmeShadowBufferEntry::fill(unsigned char *value)
{
	const BfmeShadowVector3 *lightDir = (const BfmeShadowVector3 *)value;
	BfmeShadowMeshGeometry *geometry = m_mesh->m_geometry;
	BfmeShadowIndexTriple *tri = geometry->m_lock->m_indices;
	int count = geometry->m_numPolygon;
	unsigned char *out = m_flags;

	int remainder = count;
	if (count >= 4)
	{
		unsigned int n = ((unsigned int)(count - 4) >> 2) + 1;
		remainder = count - (int)(n * 4);
		do
		{
		{
			BfmeShadowVector3 *verts0 = m_vertices;
			const BfmeShadowVector3 *pv0_0 = &verts0[tri->i0];
			const BfmeShadowVector3 *pv2_0 = &verts0[tri->i2];
			const BfmeShadowVector3 *pv1_0 = &verts0[tri->i1];

			Real v1x_0 = pv1_0->x;
			Real v1y_0 = pv1_0->y;
			Real v1z_0 = pv1_0->z;

			Real e2x_0 = v1x_0 - pv0_0->x;
			Real e2y_0 = v1y_0 - pv0_0->y;
			Real e2z_0 = v1z_0 - pv0_0->z;
			Real e1x_0 = v1x_0 - pv2_0->x;
			Real e1y_0 = v1y_0 - pv2_0->y;
			Real e1z_0 = v1z_0 - pv2_0->z;

			Real cx_0 = e1y_0 * e2z_0 - e1z_0 * e2y_0;
			Real cy_0 = e1z_0 * e2x_0 - e1x_0 * e2z_0;
			Real cz_0 = e1x_0 * e2y_0 - e1y_0 * e2x_0;

			Real dot_0 = cx_0 * lightDir->x + cy_0 * lightDir->y + cz_0 * lightDir->z;

			*out = (unsigned char)(BfmeZeroRange > dot_0);
			++tri;
			++out;
		}
		{
			BfmeShadowVector3 *verts1 = m_vertices;
			const BfmeShadowVector3 *pv0_1 = &verts1[tri->i0];
			const BfmeShadowVector3 *pv2_1 = &verts1[tri->i2];
			const BfmeShadowVector3 *pv1_1 = &verts1[tri->i1];

			Real v1x_1 = pv1_1->x;
			Real v1y_1 = pv1_1->y;
			Real v1z_1 = pv1_1->z;

			Real e2x_1 = v1x_1 - pv0_1->x;
			Real e2y_1 = v1y_1 - pv0_1->y;
			Real e2z_1 = v1z_1 - pv0_1->z;
			Real e1x_1 = v1x_1 - pv2_1->x;
			Real e1y_1 = v1y_1 - pv2_1->y;
			Real e1z_1 = v1z_1 - pv2_1->z;

			Real cx_1 = e1y_1 * e2z_1 - e1z_1 * e2y_1;
			Real cy_1 = e1z_1 * e2x_1 - e1x_1 * e2z_1;
			Real cz_1 = e1x_1 * e2y_1 - e1y_1 * e2x_1;

			Real dot_1 = cx_1 * lightDir->x + cy_1 * lightDir->y + cz_1 * lightDir->z;

			*out = (unsigned char)(BfmeZeroRange > dot_1);
			++tri;
			++out;
		}
		{
			BfmeShadowVector3 *verts2 = m_vertices;
			const BfmeShadowVector3 *pv0_2 = &verts2[tri->i0];
			const BfmeShadowVector3 *pv2_2 = &verts2[tri->i2];
			const BfmeShadowVector3 *pv1_2 = &verts2[tri->i1];

			Real v1x_2 = pv1_2->x;
			Real v1y_2 = pv1_2->y;
			Real v1z_2 = pv1_2->z;

			Real e2x_2 = v1x_2 - pv0_2->x;
			Real e2y_2 = v1y_2 - pv0_2->y;
			Real e2z_2 = v1z_2 - pv0_2->z;
			Real e1x_2 = v1x_2 - pv2_2->x;
			Real e1y_2 = v1y_2 - pv2_2->y;
			Real e1z_2 = v1z_2 - pv2_2->z;

			Real cx_2 = e1y_2 * e2z_2 - e1z_2 * e2y_2;
			Real cy_2 = e1z_2 * e2x_2 - e1x_2 * e2z_2;
			Real cz_2 = e1x_2 * e2y_2 - e1y_2 * e2x_2;

			Real dot_2 = cx_2 * lightDir->x + cy_2 * lightDir->y + cz_2 * lightDir->z;

			*out = (unsigned char)(BfmeZeroRange > dot_2);
			++tri;
			++out;
		}
		{
			BfmeShadowVector3 *verts3 = m_vertices;
			const BfmeShadowVector3 *pv0_3 = &verts3[tri->i0];
			const BfmeShadowVector3 *pv2_3 = &verts3[tri->i2];
			const BfmeShadowVector3 *pv1_3 = &verts3[tri->i1];

			Real v1x_3 = pv1_3->x;
			Real v1y_3 = pv1_3->y;
			Real v1z_3 = pv1_3->z;

			Real e2x_3 = v1x_3 - pv0_3->x;
			Real e2y_3 = v1y_3 - pv0_3->y;
			Real e2z_3 = v1z_3 - pv0_3->z;
			Real e1x_3 = v1x_3 - pv2_3->x;
			Real e1y_3 = v1y_3 - pv2_3->y;
			Real e1z_3 = v1z_3 - pv2_3->z;

			Real cx_3 = e1y_3 * e2z_3 - e1z_3 * e2y_3;
			Real cy_3 = e1z_3 * e2x_3 - e1x_3 * e2z_3;
			Real cz_3 = e1x_3 * e2y_3 - e1y_3 * e2x_3;

			Real dot_3 = cx_3 * lightDir->x + cy_3 * lightDir->y + cz_3 * lightDir->z;

			*out = (unsigned char)(BfmeZeroRange > dot_3);
			++tri;
			++out;
		}
		} while (--n);
	}

	if (remainder > 0)
	{
		do
		{
		BfmeShadowVector3 *verts = m_vertices;
		const BfmeShadowVector3 *pv0 = &verts[tri->i0];
		const BfmeShadowVector3 *pv2 = &verts[tri->i2];
		const BfmeShadowVector3 *pv1 = &verts[tri->i1];

		Real v1x = pv1->x;
		Real v1y = pv1->y;
		Real v1z = pv1->z;

		Real e2x = v1x - pv0->x;
		Real e2y = v1y - pv0->y;
		Real e2z = v1z - pv0->z;
		Real e1x = v1x - pv2->x;
		Real e1y = v1y - pv2->y;
		Real e1z = v1z - pv2->z;

		Real cx = e1y * e2z - e1z * e2y;
		Real cy = e1z * e2x - e1x * e2z;
		Real cz = e1x * e2y - e1y * e2x;

		Real dot = cx * lightDir->x + cy * lightDir->y + cz * lightDir->z;

		*out = (unsigned char)(BfmeZeroRange > dot);
		++tri;
		++out;
		} while (--remainder);
	}
}
